UPDATE t_sys_event_outbox_dlq
SET retry_count = 0,
    retry_last_time = NULL,
    retry_after_time = NULL,
    error_msg = CASE
        WHEN error_msg LIKE '[EXHAUSTED] %' THEN SUBSTRING(error_msg, 13)
        ELSE error_msg
    END,
    update_time = #{updateTime}
WHERE service_name = #{serviceName}
  AND create_time >= #{from}
  AND create_time <= #{to}
  AND delete_time IS NULL
